# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_example_from_payroll(self):
        labels = round_labels([Span(541, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_halves_round_up(self):
        labels = round_labels([Span(305, 605)], 10)
        self.assertEqual(labels, ["05:10-10:10 (5h 0m)"])

    def test_end_of_day_is_kept(self):
        labels = round_labels([Span(1000, 1440)], 60)
        self.assertEqual(labels, ["17:00-24:00 (7h 0m)"])

    def test_keeps_order_of_spans(self):
        spans = [Span(600, 660), Span(540, 600)]
        labels = round_labels(spans, 30)
        expected = [
            "10:00-11:00 (1h 0m)",
            "09:00-10:00 (1h 0m)"
        ]
        self.assertEqual(labels, expected)

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_steps_that_fit_an_hour_are_accepted(self):
        hour = [Span(0, 60)]
        for good_step in (1, 5, 6, 20, 60):
            with self.subTest(step=good_step):
                labels = round_labels(hour, good_step)
                expected = "00:00-01:00 (1h 0m)"
                self.assertEqual(labels, [expected])

    def test_bad_steps_raise(self):
        hour = [Span(0, 60)]
        for bad_step in (0, -15, 7, 90, 15.0):
            with self.subTest(step=bad_step):
                with self.assertRaises(ValueError):
                    round_labels(hour, bad_step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(541, 544)], 15)
